mapper.select:
SELECT s.id, s.student_id, s.course_id, st.student_no, st.name AS student_name, st.major, c.course_no, c.course_name, c.credit, s.usual_score, s.exam_score, s.total_score FROM scores s LEFT JOIN students st ON s.student_id = st.id LEFT JOIN courses c ON s.course_id = c.id
AND s.student_id = #{studentId}
AND s.course_id = #{courseId}
AND (st.name LIKE CONCAT('%', #{keyword}, '%') OR st.student_no LIKE CONCAT('%', #{keyword}, '%') OR c.course_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.create_time DESC
